#!/usr/bin/env python3
"""Run features/midi_filter (C only; trampoline, init-once and filter generated by build.py)
in the Blackfin simulator.

    run_gentest.py         (builds features/midi_filter first; no firmware needed)

The driver sends note-on, CC 12 and pitch bend through the generated hook. The stub at the
dispatcher address starts with the original LINK 0x10, so the generated replay runs for real.
Checks: SP/FP after every call (incl. the filtered RTS path), the dispatcher ran exactly
twice (CC 12 dropped) with the last message, init ran once, counters, R4-R6 preserved.
HLT = exit 0 = pass, ABORT = exit 1 = fail (failure bits in R7, see driver.S)."""

import json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
SDK = os.path.normpath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, os.path.join(SDK, "sim"))
from simtest import asm_bin, run_model, composed  # noqa: E402
from build import compile_project  # noqa: E402

FEATURES, APP = ["midi_filter"], "midi_filter"   # composed by tools/compose.py
V1, V2, V3 = 0x01F79000, 0x01F79010, 0x01F79020
MB1, MB2, MB3 = 0x01F79100, 0x01F79110, 0x01F79120
SCOUNT, SLAST, STACK, ZEROS = 0x01F79200, 0x01F79204, 0x01F7FFFC, 0x01F70000
DISPATCH_AT, DRIVER_AT = 0x01A85C20, 0x01F00000


def main():
    proj, cfg = composed(FEATURES, APP)
    code, syms, elf = compile_project(proj, cfg)
    hook = syms["__sdk_hook_01a85c20"]
    print(f"project: {len(code)} bytes, generated hook at {hook:#x} ({elf})")

    driver, _ = asm_bin(
        os.path.join(HERE, "driver.S"),
        DRIVER_AT,
        os.path.join(HERE, "driver"),
        {
            "STACK": STACK, "HOOK": hook,
            "V1": V1, "V2": V2, "V3": V3, "MB1": MB1, "MB2": MB2, "MB3": MB3,
            "SCOUNT": SCOUNT, "SLAST": SLAST,
            "INIT": syms["_filter_init_runs"], "PASSED": syms["_filter_midi_passed"],
            "DROPPED": syms["_filter_midi_dropped"],
        },
    )
    stub, _ = asm_bin(
        os.path.join(HERE, "dispatch_stub.S"),
        DISPATCH_AT,
        os.path.join(HERE, "dispatch_stub"),
        {"SCOUNT": SCOUNT, "SLAST": SLAST},
        entry="_dispatch",
    )
    r = run_model(
        os.path.join(HERE, "gentest_run.elf"),
        [(DISPATCH_AT, stub), (0x01E00000, code), (DRIVER_AT, driver), (ZEROS, bytes(0x10000))],
        DRIVER_AT,
    )
    print(
        "checks: SP/FP after 3 calls (incl. filtered), dispatcher calls==2, last msg, "
        "init once, passed==2, dropped==1, R4-R6 preserved"
    )
    print("PASS" if r.returncode == 0 else f"FAIL (exit {r.returncode}; read R7 in bfin-elf-gdb)")
    sys.exit(r.returncode)


if __name__ == "__main__":
    main()
